function paint(rows: string[], pal: Record<string, string>): HTMLCanvasElement {
  const w = Math.max(...rows.map(r => r.length));
  const p = new PixelCanvas(w, rows.length);
  rows.forEach((r, y) => [...r].forEach((ch, x) => ch !== '.' && pal[ch] && p.px(x, y, pal[ch])));
  return p.outline('auto', 0.22).toCanvas();
}

/** The hand-drawn creatures (by texture key). */
export const DRAWN_CREATURES = Object.keys(ART);

/** Frames of one of the hand-drawn creatures (its texture key: 'bonehound', 'wolf', 'garrick'...). */
export function creatureFrames(id: string): HTMLCanvasElement[] {
  const a = ART[id];
  return a.frames.map(f => paint(f, a.pal));
}
